class Get_most_popular_tv_shows(API_base):
    """
    Retrieve the most popular TV shows from IMDb based on user location.
    """
    def __init__(self):
        pass

    def execute(self, **params):
        expected_params = set(["p_purchaseCountry", "p_homeCountry", "p_currentCountry"])
        unexpected_params = set(params.keys()) - expected_params 
        if unexpected_params:
            return self.handle_error(f"Unexpected parameters: {', '.join(unexpected_params)}", 400)
        p_purchaseCountry = params.get('p_purchaseCountry', None)
        if p_purchaseCountry is None:
            return self.handle_error(f"Required parameter 'p_purchaseCountry' is missing", 400)
        is_valid, error = self.validate_type(p_purchaseCountry, 'p_purchaseCountry', str)
        if not is_valid:
            return error
        
        if p_purchaseCountry is not None and p_purchaseCountry not in ["US", "GB", "DE", "IN", "IT", "FR", "JP", "CA", "ES"]:
            return self.handle_error(f"Parameter 'p_purchaseCountry' not in valid enum", 400)
        
        p_homeCountry = params.get('p_homeCountry', None)
        if p_homeCountry is None:
            return self.handle_error(f"Required parameter 'p_homeCountry' is missing", 400)
        is_valid, error = self.validate_type(p_homeCountry, 'p_homeCountry', str)
        if not is_valid:
            return error
        
        if p_homeCountry is not None and p_homeCountry not in ["US", "GB", "DE", "IN", "IT", "FR", "JP", "CA", "ES"]:
            return self.handle_error(f"Parameter 'p_homeCountry' not in valid enum", 400)
        
        p_currentCountry = params.get('p_currentCountry', None)
        if p_currentCountry is None:
            return self.handle_error(f"Required parameter 'p_currentCountry' is missing", 400)
        is_valid, error = self.validate_type(p_currentCountry, 'p_currentCountry', str)
        if not is_valid:
            return error
        
        if p_currentCountry is not None and p_currentCountry not in ["AR", "AU", "CA", "CL", "ES", "DE", "IT", "MX", "NZ", "PT", "ES", "GB", "US"]:
            return self.handle_error(f"Parameter 'p_currentCountry' not in valid enum", 400)
        
        return {
            "status_code": 200, 
            "results": {
                "function_name": "Get_most_popular_tv_shows",
                "p_purchaseCountry": p_purchaseCountry,
                "p_homeCountry": p_homeCountry,
                "p_currentCountry": p_currentCountry
            }
        }

