class Health_risk_assessment(API_base):
    """
    Evaluates the risk of developing cancer based on lifestyle choices and genetic predisposition.
    """
    def __init__(self):
        pass

    def execute(self, **params):
        expected_params = set(["p_lifestyle_factors", "p_genetic_factors"])
        unexpected_params = set(params.keys()) - expected_params 
        if unexpected_params:
            return self.handle_error(f"Unexpected parameters: {', '.join(unexpected_params)}", 400)
        p_lifestyle_factors = params.get('p_lifestyle_factors', None)
        if p_lifestyle_factors is None:
            return self.handle_error(f"Required parameter 'p_lifestyle_factors' is missing", 400)
        is_valid, error = self.validate_type(p_lifestyle_factors, 'p_lifestyle_factors', dict)
        if not is_valid:
            return error
        

        p_diet = p_lifestyle_factors.get('p_diet', None)
        if p_diet is not None:
            is_valid, error = self.validate_type(p_diet, 'p_diet', str)
            if not is_valid:
                return error
        
        if p_diet is not None and p_diet not in ["High-fat", "Low-fat", "Vegetarian", "Vegan", "Balanced"]:
            return self.handle_error(f"Parameter 'p_diet' not in valid enum", 400)
        
        p_exercise_frequency = p_lifestyle_factors.get('p_exercise_frequency', None)
        if p_exercise_frequency is not None:
            is_valid, error = self.validate_type(p_exercise_frequency, 'p_exercise_frequency', str)
            if not is_valid:
                return error
        
        if p_exercise_frequency is not None and p_exercise_frequency not in ["None", "Sporadic", "Regular", "Daily"]:
            return self.handle_error(f"Parameter 'p_exercise_frequency' not in valid enum", 400)
        
        p_alcohol_consumption = p_lifestyle_factors.get('p_alcohol_consumption', None)
        if p_alcohol_consumption is not None:
            is_valid, error = self.validate_type(p_alcohol_consumption, 'p_alcohol_consumption', str)
            if not is_valid:
                return error
        
        if p_alcohol_consumption is not None and p_alcohol_consumption not in ["None", "Light", "Moderate", "Heavy"]:
            return self.handle_error(f"Parameter 'p_alcohol_consumption' not in valid enum", 400)
        
        p_sun_exposure = p_lifestyle_factors.get('p_sun_exposure', None)
        if p_sun_exposure is not None:
            is_valid, error = self.validate_type(p_sun_exposure, 'p_sun_exposure', dict)
            if not is_valid:
                return error
        
        if p_sun_exposure is not None:

            p_duration = p_sun_exposure.get('p_duration', None)
            if p_duration is None:
                return self.handle_error(f"Required parameter 'p_duration' is missing", 400)
            is_valid, error = self.validate_type(p_duration, 'p_duration', str)
            if not is_valid:
                return error
            
            p_protection = p_sun_exposure.get('p_protection', None)
            if p_protection is not None:
                is_valid, error = self.validate_type(p_protection, 'p_protection', str)
                if not is_valid:
                    return error
            
            if p_protection is not None and p_protection not in ["None", "SPF 15+", "SPF 30+", "SPF 50+"]:
                return self.handle_error(f"Parameter 'p_protection' not in valid enum", 400)
            
        p_genetic_factors = params.get('p_genetic_factors', None)
        if p_genetic_factors is not None:
            is_valid, error = self.validate_type(p_genetic_factors, 'p_genetic_factors', list)
            if not is_valid:
                return error
        
        return {
            "status_code": 200, 
            "results": {
                "function_name": "Health_risk_assessment",
                "p_lifestyle_factors": p_lifestyle_factors,
                "p_genetic_factors": p_genetic_factors
            }
        }

