class Book_recommendation_genre_based(API_base):
    """
    Provides a list of book recommendations based on the specified genre and user preferences.
    """
    def __init__(self):
        pass

    def execute(self, **params):
        expected_params = set(["p_genre", "p_preferences"])
        unexpected_params = set(params.keys()) - expected_params 
        if unexpected_params:
            return self.handle_error(f"Unexpected parameters: {', '.join(unexpected_params)}", 400)
        p_genre = params.get('p_genre', None)
        if p_genre is None:
            return self.handle_error(f"Required parameter 'p_genre' is missing", 400)
        is_valid, error = self.validate_type(p_genre, 'p_genre', str)
        if not is_valid:
            return error
        
        p_preferences = params.get('p_preferences', None)
        if p_preferences is not None:
            is_valid, error = self.validate_type(p_preferences, 'p_preferences', dict)
            if not is_valid:
                return error
        
        if p_preferences is not None:

            p_author = p_preferences.get('p_author', None)
            if p_author is None:
                return self.handle_error(f"Required parameter 'p_author' is missing", 400)
            is_valid, error = self.validate_type(p_author, 'p_author', str)
            if not is_valid:
                return error
            
            p_publicationYear = p_preferences.get('p_publicationYear', None)
            if p_publicationYear is None:
                return self.handle_error(f"Required parameter 'p_publicationYear' is missing", 400)
            is_valid, error = self.validate_type(p_publicationYear, 'p_publicationYear', str)
            if not is_valid:
                return error
            
            if p_publicationYear is not None and p_publicationYear not in ["2020s", "2010s", "2000s", "1990s", "1980s", "Pre-1980"]:
                return self.handle_error(f"Parameter 'p_publicationYear' not in valid enum", 400)
            
            p_rating = p_preferences.get('p_rating', None)
            if p_rating is not None:
                is_valid, error = self.validate_type(p_rating, 'p_rating', dict)
                if not is_valid:
                    return error
            
            if p_rating is not None:

                p_minRating = p_rating.get('p_minRating', None)
                if p_minRating is None:
                    return self.handle_error(f"Required parameter 'p_minRating' is missing", 400)
                is_valid, error = self.validate_type(p_minRating, 'p_minRating', (float, int))
                if not is_valid:
                    return error
                if p_minRating is not None:
                    p_minRating = float(p_minRating)
                
                p_maxRating = p_rating.get('p_maxRating', None)
                if p_maxRating is not None:
                    is_valid, error = self.validate_type(p_maxRating, 'p_maxRating', (float, int))
                    if not is_valid:
                        return error
                if p_maxRating is not None:
                    p_maxRating = float(p_maxRating)
                
        return {
            "status_code": 200, 
            "results": {
                "function_name": "Book_recommendation_genre_based",
                "p_genre": p_genre,
                "p_preferences": p_preferences
            }
        }

